export const MODEL='company-life-1';
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const round=v=>Math.round(v*100)/100;
export function validate(c){if(c.unit!=='万円 / 四半期'||!c.version||c.scope!=='架空の小規模受託ソフトウェア会社・創業5年以内')throw Error('設定の単位・版・適用対象が不正です');for(const k of ['founderPay','employeePay','overhead','capacityPerPerson','collectionShare','quarterlyInterest','quarterlyPrincipal','hireChance','delayChance','departureChance','salesChance','contractionChance','macroStay'])if(!Number.isFinite(c.parameters[k])||c.parameters[k]<0)throw Error('設定値が欠測または不正: '+k);for(const k of ['collectionShare','quarterlyInterest','hireChance','delayChance','departureChance','salesChance','contractionChance','macroStay'])if(c.parameters[k]>1)throw Error('確率・割合の範囲が不正: '+k);return c;}
export function rng(s){s.rng=(s.rng+0x6D2B79F5)>>>0;let t=s.rng;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;}
export function create(seed,name,config){validate(config);let s={model:MODEL,config:structuredClone(config),seed:seed>>>0,rng:seed>>>0,name:name||'こもれびソフト',q:0,cash:0,debt:300,staff:1,experience:0,skill:1,trust:55,fatigue:0,macro:1,backlog:0,receivables:[],investments:[],clients:[],history:[],cooldowns:{},ended:null};s.experience=3+Math.floor(rng(s)*9);s.staff=rng(s)<.35?2:1;s.cash=round(780+rng(s)*340+(s.staff-1)*180);s.clients=[{name:'街の商社',value:round(160+rng(s)*60)},{name:'地域のメーカー',value:round(140+rng(s)*60)}];s.macro=Math.floor(rng(s)*3);s.initial={cash:s.cash,staff:s.staff,experience:s.experience};s.last={revenue:0,profit:0,events:[{title:'小さな事務所に、最初の灯り。',text:`${s.experience}年の開発経験と、顔の見える取引先2社。${s.staff+1}人で会社の一歩目を踏み出す。`,kind:'start'}],action:'創業',load:0};return s;}
export const costs=s=>s.config.parameters.founderPay+s.staff*s.config.parameters.employeePay+s.config.parameters.overhead;
export function choices(s){let a=[];const cash=s.cash,load=s.last.load;if(cash<costs(s)*1.7){if(s.debt<=600)a.push({id:'loan',title:'運転資金を借りる',cost:0,tag:'資金繰り',desc:'300万円を調達。借入残高と利息が増えます。',effect:'融資実行は確定。元本返済は毎期最大25万円。'});if(s.staff>0)a.push({id:'shrink',title:'小さな体制に戻す',cost:45,tag:'固定費を見直す',desc:'従業員を1人減らし、毎期の給与を130万円削減。',effect:'整理費用45万円。対応できる仕事も減ります。'});}
if(load>.8&&cash>costs(s)*1.25)a.push({id:'hire',title:'次の仲間を探す',cost:35,tag:'採用・育成',desc:'採用活動に35万円。採用できれば次期から1人増員。',effect:'採用は不確実。成功すると次期から給与が増加。'});
if(s.clients.length<5)a.push({id:'sales',title:'まだ見ぬ顧客に会う',cost:25,tag:'新規開拓',desc:'営業活動に25万円。新しい取引先との出会いを探す。',effect:'契約できれば今期から受注。取れない期もあります。'});
if(s.fatigue>35||s.trust<55)a.push({id:'care',title:'いまの約束を大切に',cost:20,tag:'信頼・チーム',desc:'顧客とのすり合わせとチームの負担軽減に20万円。',effect:'信頼 +10、疲労 −18。今期の契約縮小リスクを抑えます。'});
if(cash>costs(s)*1.7&&!s.investments.length&&s.skill<1.7)a.push({id:'invest',title:'仕事の仕組みを整える',cost:65,tag:'業務改善',desc:'開発環境と手順の改善に65万円を投じる。',effect:'2四半期後、1人あたりの処理能力が12%分上昇。'});
if(load>1.15)a.push({id:'outsource',title:'外の力を借りる',cost:90,tag:'納期を守る',desc:'今期だけ90万円で外注し、処理能力を180万円分増やす。',effect:'余裕が生まれる一方、仕事が足りなくても費用は発生。'});
a=a.slice(0,3).filter(x=>x.cost<cash);a.push({id:'keep',title:'今の歩幅で続ける',cost:0,tag:'現状を維持',desc:'追加の施策費をかけず、いまある仕事を進める。',effect:'給与・固定費・返済は通常どおり発生します。'});return a;}
const clientNames=['町の食品会社','小さな出版社','物流の会社','地元の工務店','海辺の旅館','新しい小売店','老舗の専門店'];
export function step(prev,action){if(prev.ended)throw Error('終了済み');const s=structuredClone(prev),p=s.config.parameters;const choice=choices(s).find(c=>c.id===action);if(!choice)throw Error('実行できない選択');s.q++;let events=[],special=choice.cost,borrow=0,hired=false,oldAr=s.receivables.reduce((a,r)=>a+r.amount,0),startCash=s.cash,startDebt=s.debt;const emit=(title,text,kind='ordinary')=>events.push({title,text,kind});
if(action==='loan'){borrow=300;s.debt+=borrow;emit('少し先まで、息がつける。','運転資金300万円を調達。売上や利益には含めません。','choice');}
if(action==='shrink'){s.staff--;emit('大きくするだけが、経営ではない。','1人少ない体制へ。今期から給与と処理能力が減りました。','choice');}
if(action==='care'){s.trust=clamp(s.trust+10,0,100);s.fatigue=clamp(s.fatigue-18,0,100);emit('約束を、もう一度確かめる。','顧客と優先順位を揃え、チームの負担を減らしました。','choice');}
if(action==='invest'){s.investments.push({due:s.q+2,from:s.q});emit('未来の仕事に、道具を贈る。',`${s.q+2}期目に改善が完了する予定です。`,'choice');}
if(action==='hire'){hired=rng(s)<p.hireChance;emit(hired?'一緒に働きたい人に、出会えた。':'今回は、縁がつながらなかった。',hired?'採用が決まりました。新しい仲間は次の四半期から参加します。':'採用費35万円は支出。人員は変わりません。','choice');}
for(const i of s.investments.filter(i=>i.due===s.q)){s.skill=round(s.skill+.12);emit('あの日の改善が、実を結ぶ。',`${i.from}期目の投資で、処理能力の倍率が0.12上がりました。`,'turning');}s.investments=s.investments.filter(i=>i.due>s.q);
if(rng(s)>p.macroStay){const old=s.macro;s.macro=Math.floor(rng(s)*3);if(old!==s.macro)emit(['街の注文が、少し慎重に。','いつものペースが戻ってきた。','街に、新しい仕事の気配。'][s.macro],['不調な景気は取引先全体の注文を抑えます。','景気が平常に移りました。','好調な景気が取引先全体の注文を後押しします。'][s.macro],'world');}
if(action==='sales'){if(rng(s)<p.salesChance+s.experience*.008){let value=round(65+rng(s)*80);let name=clientNames.find(n=>!s.clients.some(c=>c.name===n))||'紹介の取引先';s.clients.push({name,value});emit('一本の営業が、新しいご縁に。',`${name}との契約が成立。基準受注額が毎期${Math.round(value)}万円増えました。`,'turning');}else emit('名刺は増えた。契約は、まだ。','今期の営業は成約に至らず。営業費25万円を支出しました。','choice');}
if(s.clients.length&&s.q>(s.cooldowns.contract||0)&&rng(s)<p.contractionChance*(s.macro===0?1.7:1)*(action==='care'?.3:1)){let c=s.clients[Math.floor(rng(s)*s.clients.length)],lost=round(c.value*.4);c.value=round(c.value-lost);s.cooldowns.contract=s.q+2;emit('先方から、予算見直しの連絡。',`${c.name}の基準受注が毎期${Math.round(lost)}万円減少。次の開拓を考える時かもしれません。`,'risk');}
if(s.clients.length&&rng(s)<.12){let c=s.clients[Math.floor(rng(s)*s.clients.length)];c.value=round(c.value+25);emit('いつものお客さまから、次の相談。',`${c.name}の追加発注で、基準受注が毎期25万円増えました。`,'turning');}
let demand=round(s.clients.reduce((a,c)=>a+c.value,0)*[.78,1,1.16][s.macro]*(.88+rng(s)*.24)*(1+(s.trust-55)/500));let capacity=round((s.staff+1)*p.capacityPerPerson*s.skill*(1-s.fatigue/500)+(action==='outsource'?180:0));let work=demand+s.backlog;let revenue=round(Math.min(work,capacity));s.backlog=round(Math.max(0,work-capacity));let load=work/capacity;s.fatigue=clamp(s.fatigue+(load>1.1?13:-9),0,100);if(s.backlog>capacity*.75){let lost=round(s.backlog-capacity*.75);s.backlog=round(capacity*.75);s.trust=clamp(s.trust-8,0,100);emit('引き受けた仕事が、追いつかない。',`未完了案件${Math.round(lost)}万円分が取り消しに。未売上のため損失の二重計上はしません。`,'risk');}
let collections=0,ar=[];for(const r of s.receivables){if(r.due<=s.q)collections+=r.amount;else ar.push(r);}let currentCollection=round(revenue*p.collectionShare),delayed=false;if(s.q>(s.cooldowns.delay||0)&&rng(s)<p.delayChance){delayed=true;s.cooldowns.delay=s.q+2;ar.push({amount:currentCollection,due:s.q+1});currentCollection=0;emit('利益はある。でも、入金がまだ。',`当期入金予定${Math.round(revenue*p.collectionShare)}万円を次期に繰越。売上はそのままです。`,'risk');}collections=round(collections+currentCollection);ar.push({amount:round(revenue-revenue*p.collectionShare),due:s.q+1});s.receivables=ar;let operating=round(costs(s)+special),interest=round(s.debt*p.quarterlyInterest),repay=round(Math.min(p.quarterlyPrincipal,s.debt)),profit=round(revenue-operating-interest);s.debt=round(s.debt-repay);s.cash=round(startCash+collections+borrow-operating-interest-repay);
if(s.staff>0&&s.q>(s.cooldowns.departure||0)&&rng(s)<p.departureChance+(s.fatigue>60?.12:0)){s.staff--;s.cooldowns.departure=s.q+3;emit('仲間が、別の道へ歩き出す。','退職が決まり、次期の処理能力と給与が減ります。','risk');}if(hired)s.staff++;
if(!events.length)emit('特別なことのない、いい四半期。',`目の前の仕事を納め、${Math.round(revenue)}万円の売上を積み重ねました。`);
if(s.cash<costs(s)*1.4&&s.cash>=0)emit('次の支払いに、備えたい。',`手元資金は通常費用の約${(s.cash/costs(s)).toFixed(1)}四半期分。資金調達や体制見直しを検討できます。`,'risk');
s.last={action:choice.title,actionId:action,revenue,profit,operating,interest,repay,borrow,collections,oldAr,newAr:round(ar.reduce((a,r)=>a+r.amount,0)),startCash,startDebt,deltaCash:round(s.cash-startCash),load:round(load),demand,capacity,delayed,events};s.history.push({q:s.q,cash:s.cash,debt:s.debt,staff:s.staff,...structuredClone(s.last)});if(s.cash<0)s.ended='insolvent';else if(s.q>=20)s.ended='five-years';return s;}
export function close(s){const n=structuredClone(s);n.ended='closed';return n;}
export function restore(raw){const s=JSON.parse(raw);if(s.model!==MODEL)throw Error('このセーブは異なるモデル版です。元の記録をダウンロードして保管できます。');validate(s.config);if(!Number.isInteger(s.q)||s.q<0||s.q>20||!Number.isFinite(s.cash)||!Array.isArray(s.history)||!Number.isInteger(s.rng))throw Error('セーブ形式を読み込めません。記録は削除していません。');return s;}
